// Command settingscatalogue writes the settings catalogue as `GET /settings/catalogue` answers it,
// so that the web app's tests hold every declared setting to a screen and a name (configuration
// model.md §4: a setting missing from a door fails a gate), and the who-configures-what matrix of
// the documentation: each setting at each level that decides it, the writer it asks for and the
// shipped roles that carry it. Generated by `make generate` and committed, so a newly declared
// setting without a screen fails the Node lane, which runs no Go, and a matrix that drifted from
// the catalogue fails `make gate-quick`.
//
// Usage: settingscatalogue <out.json> [<matrix.md>]
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"

	"github.com/Jersyfi/hubtask/core/application/service/setting"
	"github.com/Jersyfi/hubtask/core/domain/model/identity"
	domain "github.com/Jersyfi/hubtask/core/domain/model/setting"
	"github.com/Jersyfi/hubtask/core/domain/service"
)

func main() {
	if len(os.Args) != 2 && len(os.Args) != 3 {
		fmt.Fprintln(os.Stderr, "usage: settingscatalogue <out.json> [<matrix.md>]")
		os.Exit(2)
	}
	catalogue, err := setting.Catalogue()
	if err != nil {
		fail(err)
	}
	body, err := json.MarshalIndent(setting.CatalogueOutput(catalogue.Definitions()), "", "  ")
	if err != nil {
		fail(err)
	}
	if err := os.WriteFile(os.Args[1], append(body, '\n'), 0o644); err != nil { //nolint:gosec // a committed, public file
		fail(err)
	}
	if len(os.Args) == 3 {
		if err := os.WriteFile(os.Args[2], []byte(matrix(catalogue.Definitions())), 0o644); err != nil { //nolint:gosec // a committed, public file
			fail(err)
		}
	}
}

func fail(err error) {
	fmt.Fprintln(os.Stderr, err)
	os.Exit(1)
}

// matrix renders who may change which setting at which level. A writer that is a permission is
// answered with the shipped roles that carry it; a workspace's own roles carry what they were
// given, which *Who may do what* answers for the workspace at hand.
func matrix(definitions []domain.Definition) string {
	shipped := map[string][]identity.Role{}
	for _, entry := range service.PermissionCatalogue() {
		shipped[string(entry.Permission)] = entry.Shipped
	}
	var page strings.Builder
	page.WriteString(`<!-- Generated by tools/settingscatalogue from the settings catalogue. Do not edit by hand:
     run "make generate", which is what the pull request check runs and fails on a diff of. -->

# Who configures what

Every setting of the [settings catalogue](../../core/application/service/setting/Catalogue.go), at
each level that may decide it, with what a writer needs there (configuration/model.md §4). At the
installation and a plan the writer is the operator (` + "`admin:instance`" + `); at a person's own level
the person alone. In a workspace, a hub and a collection the writer is a permission, carried by the
shipped roles named here and by any custom role given it - *People → Permissions* answers that for
one workspace, by person and place.

| Setting | Level | Writer needs | Shipped roles that carry it |
|---|---|---|---|
`)
	for _, definition := range definitions {
		for _, level := range definition.Levels {
			writer := definition.Writers[level]
			carriers := "-"
			switch {
			case level == domain.LevelInstance || level == domain.LevelPlan:
				carriers = "the installation's operators"
			case writer == domain.PersonOwnWriter:
				carriers = "the person"
			default:
				names := make([]string, 0, len(shipped[writer]))
				for _, role := range shipped[writer] {
					names = append(names, string(role))
				}
				if len(names) > 0 {
					carriers = strings.Join(names, ", ")
				}
			}
			fmt.Fprintf(&page, "| `%s` | %s | `%s` | %s |\n", definition.Key, level, writer, carriers)
		}
	}
	return page.String()
}
